export const dynamic = 'force-dynamic';

import { Suspense } from 'react';
import { UnifiedFeed } from '@/components/unified-feed';
import { FeedSkeleton } from '@/components/unified-feed/feed-skeleton';
import {
  searchJobsWithHighlights,
  getAllDomains,
  getAllSkills,
} from '@/app/actions';
import { isAuthEnabled } from '@/lib/auth-config';
import type { HighlightType } from '@/lib/data-types';

interface SearchParams {
  q?: string;
  types?: string;
  domains?: string;
  skills?: string;
  metrics?: string;
}

export default async function AppPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>;
}) {
  let session = null;

  if (isAuthEnabled()) {
    const { auth } = await import('@/auth');
    session = await auth();
  }

  const params = await searchParams;

  // Parse filters from URL
  const filters = {
    query: params.q || undefined,
    types: params.types?.split(',').filter(Boolean) as HighlightType[] | undefined,
    domains: params.domains?.split(',').filter(Boolean) || undefined,
    skills: params.skills?.split(',').filter(Boolean) || undefined,
    onlyWithMetrics: params.metrics === 'true' || undefined,
  };

  if (session?.user) {
    // Authenticated: server-side fetch
    // getDataLayer() auto-provisions the DB for new users, but keep try/catch as safety net
    try {
      const [jobs, domains, skills] = await Promise.all([
        searchJobsWithHighlights(filters),
        getAllDomains(),
        getAllSkills(),
      ]);

      return (
        <Suspense fallback={<FeedSkeleton />}>
          <UnifiedFeed
            initialJobs={jobs}
            domains={domains}
            skills={skills}
            searchJobsAction={searchJobsWithHighlights}
            mode="authenticated"
          />
        </Suspense>
      );
    } catch {
      // DB not yet provisioned — render empty, MigrationHandler will handle setup
      return (
        <Suspense fallback={<FeedSkeleton />}>
          <UnifiedFeed
            initialJobs={[]}
            domains={[]}
            skills={[]}
            searchJobsAction={searchJobsWithHighlights}
            mode="authenticated"
          />
        </Suspense>
      );
    }
  }

  // Anonymous: pass empty initial data, UnifiedFeed loads from IndexedDB
  return (
    <Suspense fallback={<FeedSkeleton />}>
      <UnifiedFeed
        initialJobs={[]}
        domains={[]}
        skills={[]}
        searchJobsAction={searchJobsWithHighlights}
        mode="anonymous"
      />
    </Suspense>
  );
}
